<script setup lang="ts">import { ref } from 'vue';import { api,post } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';type RunCommand='pause'|'resume'|'cancel'|'retry';const id=ref(''),run=ref<any>(),timeline=ref<any[]>([]),error=ref(''),loading=ref(false);async function load(){loading.value=true;error.value='';try{run.value=await api(`/runs/${id.value}`);timeline.value=await api(`/runs/${id.value}/timeline`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}async function command(name:RunCommand){try{await post(`/runs/${id.value}/${name}`,{reason:`operator ${name}`});await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Run control</h2><p>Durable lifecycle and resumable stage history.</p></div><div class="inline"><input v-model="id" placeholder="run_id"><button @click="load">Open</button></div></div><AsyncState :loading="loading" :error="error" :empty="!run"><div v-if="run" class="run-state"><strong>{{run.state}}</strong><span class="mono">{{run.manifest_digest}}</span></div><div class="inline"><button class="secondary" @click="command('pause')">Pause</button><button class="secondary" @click="command('resume')">Resume</button><button class="danger" @click="command('cancel')">Cancel</button></div><ol class="timeline"><li v-for="event in timeline" :key="event.transition_id"><b>{{event.to_state}}</b><span>{{event.reason}} · {{event.occurred_at}}</span></li></ol></AsyncState></section></template>
